cd /Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature; python3 - <<'PY'
import pathlib
p = pathlib.Path('tests/codegen/objects/gc_aliasing.rs')
t = p.read_text()
OLD = '''echo count($uniq) . "|" . $uniq[0][0] . "|" . $uniq[2][0];
echo count($uniq) . "|" . $uniq[0][0];
"#,
    );
    assert_eq!(out, "1|3");'''
NEW = '''echo count($uniq) . "|" . $uniq[0][0];
"#,
    );
    // MEASURED on `php -n` 8.5.6. The program used to read `$uniq[2][0]` too — an index
    // `array_unique()` has just removed — so it asserted `1|3` against an output that was really
    // `1|3|1|3` plus two warnings about the missing key. The borrowed inner array surviving both
    // `unset()`s is what this test is for, and one read shows it.
    assert_eq!(out, "1|3");'''
assert t.count(OLD) == 1, 'the gc assertion is not where it was read'
p.write_text(t.replace(OLD, NEW, 1))
print('the test asserts what php answers')
